// รูปจาก Lazada CDN ถูกเสิร์ฟเป็น AVIF (x-oss-process=.../format,avif)
// Telegram/Facebook/Instagram ไม่รองรับ AVIF -> บังคับให้ CDN คืนเป็น JPEG
function toJpg(u){
  if(!u) return u;
  try{
    if(u.indexOf('x-oss-process')!==-1){
      u=u.replace(/format,(avif|webp|heic|heif)/gi,'format,jpg');
      if(!/format,jpg/i.test(u)) u=u+'/format,jpg';
    }
    u=u.replace(/\.(avif|webp)(\?|$)/i,'$2').replace(/\.jpg_(\?|$)/i,'.jpg$1');
  }catch(e){}
  return u;
}

