const deal = $('Split Approved').item.json;
const all = $('Split Approved').all().map(x => x.json);
const idx = all.findIndex(a => a.page_id === deal.page_id);
function pick(node, i){ try { const arr = $(node).all(); return (i >= 0 && arr[i]) ? arr[i].json : null; } catch (e) { return null; } }
function errOf(j){ try { const m = (j && j.error && (j.error.message || j.error.error_user_msg)) || (j && j.message) || ''; return String(m).replace(/\s+/g, ' ').slice(0, 70); } catch (e) { return ''; } }

let tg = '❌ ไม่สำเร็จ';
const tv = pick('TG Verify', idx);
if (tv && tv.sent === true) tg = '✅ รูป+แคปชัน';
else if (tv && tv.sent === false) tg = '⚠️ ข้อความล้วน (รูปไม่ผ่าน)';

let fb = '❌ ไม่สำเร็จ';
const fv = pick('FB Verify', idx);
if (fv && fv.sent === true) fb = '✅ รูป+แคปชัน';
else if (fv && fv.sent === false) fb = '⚠️ ข้อความ+ลิงก์ (รูปไม่ผ่าน)';

// #20: ดีลที่ถูกจำกัดโควตา Threads (skip) ไม่มีผลใน Threads Publish — จับคู่ตามลำดับเฉพาะดีลที่ไม่ข้าม
let btpAll = []; try { btpAll = $('Build Threads Post').all().map(x => x.json); } catch (e) {}
const btp = btpAll.find(x => x.page_id === deal.page_id) || btpAll[idx] || null;
const thSkipped = !!(btp && btp.skip);
let thj = null;
if (!thSkipped) { try { thj = $('Threads Publish').item.json; } catch (e) { const nz = btpAll.slice(0, idx).filter(x => !x.skip).length; thj = pick('Threads Publish', nz); } }
let th;
if (thSkipped) {
  th = '⏭ ข้าม (จำกัด 2 ดีล/รอบ)';
} else if (thj && thj.id) {
  let mode = '';
  try { mode = $('Build Threads Post').item.json.mode || ''; } catch (e) {}
  th = (mode === 'TEXT') ? '✅ ข้อความล้วน' : '✅ รูป+แคปชัน';
} else {
  const m = errOf(thj);
  th = '❌ ไม่สำเร็จ' + (m ? ' — ' + m : '');
}

const text = '✅ โพสต์แล้ว: ' + (deal.name || '-') + '\n' +
  '• Telegram: ' + tg + '\n' +
  '• Facebook: ' + fb + '\n' +
  '• Threads: ' + th +
  (deal.link ? '\n' + deal.link : '');
return { json: { alert: text, name: deal.name } };

const d=$('Split Approved').item.json;
let img=null;
try{
  const imgs=$json.images;
  if(Array.isArray(imgs)&&imgs.length){
    const big=imgs.slice().sort((a,b)=>(b.width||0)-(a.width||0))[0];
    if(big&&big.source)img=big.source;
  }
}catch(e){}
let text=(d.caption||'').trim();
// IG กดลิงก์ในแคปชันไม่ได้ -> ตัดบรรทัดที่มีลิงก์ทิ้ง
let lines=text.split('\n').filter(l=>l.indexOf('http')===-1);
// ดึงแฮชแท็กออกจากเนื้อความไปรวมไว้ท้ายโพสต์ที่เดียว + ตัดหมายเหตุ (ลิงก์ affiliate) ที่ไม่มีความหมายบน IG
const found=[];
lines=lines.map(function(l){
  l=l.replace(/\(\s*ลิงก์\s*affiliate\s*\)/g,'');
  const m=l.match(/#[^\s#]+/g);
  if(m)m.forEach(function(t){found.push(t);});
  return l.replace(/#[^\s#]+/g,'').replace(/[ \t]+/g,' ').trim();
});
let body=lines.join('\n').replace(/\n{3,}/g,'\n\n').trim();
const cat=(d.cat||'').trim();
const base=['#ป้ายยา','#ดีลเด็ด','#ของถูก','#รีวิวของดี','#ช้อปปิ้งออนไลน์'];
if(cat)base.push('#'+cat.replace(/\s/g,''));
const tags=[];
found.concat(base).forEach(function(t){if(tags.indexOf(t)===-1)tags.push(t);});
// 28 ก.ย. 69: IG จำกัดบัญชี 30 วัน ฐาน "prohibited commercial practices" — เลิก 'กดลิงก์ในไบโอ' ซ้ำทุกโพสต์ · สลับสำนวน บอกชื่อเว็บเป็นข้อความ · เปิดเผยลิงก์พันธมิตร
const ctas=['ดูรายละเอียดดีลนี้ได้ที่ paiyaadeals.com','รวมดีลทั้งหมดอยู่ที่ paiyaadeals.com','เข้าไปดูราคาล่าสุดที่ paiyaadeals.com ได้เลย','ดีลนี้และดีลอื่น ๆ รวมไว้ที่ paiyaadeals.com'];
let hsh=0; for (const ch of (d.name||'')) hsh=(hsh*31+ch.charCodeAt(0))>>>0;
let caption=body+'\n\n'+ctas[hsh%ctas.length]+'\nลิงก์พันธมิตร มีค่าคอมมิชชั่น #ad\n\n'+tags.join(' ');
if(caption.length>2100)caption=caption.slice(0,2099);
let pid = null; try { pid = $('Split Approved').item.json.page_id || null; } catch (e) {}
return { json: { igImage:img, igCaption:caption, hasImage:!!img, page_id: pid } };

// IG Reel: สร้าง container Reels → ให้ container deal-video (VPS) เรนเดอร์คลิปแล้วอัปโหลดเข้า rupload เอง
// → รอ Meta ประมวลผล → publish · ล้มขั้นไหนก็ตาม → reelOk:false แล้ว "IG Reel OK?" ส่งไปโพสต์ภาพแบบเดิม (ดีลห้ามหายจาก IG)
// ที่ไม่ส่งไฟล์ผ่าน node นี้เพราะ task runner serialize Buffer เพี้ยน (Meta ตอบ Video Transcoding Error)
// ซอร์สเรนเดอร์: repo deal-poster vps/deal-video/service/server.py
const IG = '17841440317177953';
const V = 'v21.0';
const TOKEN = 'REPLACE_FB_PAGE_TOKEN';
const DRY_RUN = false;
const CREDIT = '🎵 Carefree — Kevin MacLeod (incompetech.com) · CC BY 4.0';
const TG_BOT = 'REPLACE_TELEGRAM_BOT_TOKEN';   // token บอท @sup_dealposter_bot (ใช้ 2 จุด: คลิปปกติ + review Veo)
const sleep = ms => new Promise(r => setTimeout(r, ms));
const mask = s => String(s).replace(/EAA[A-Za-z0-9]+/g, '<TOKEN>').slice(0, 500);
// #19 28 ก.ย. 69: node นี้อยู่ใน Loop Reels (ทีละดีล) → จับคู่ดีลด้วย page_id ก่อน (pairedItem ผ่าน SplitInBatches ไม่ไว้ใจ) ค่อยถอยไป .item
let d = null;
try { const all = $('Split Approved').all().map(x => x.json); d = $json.page_id ? all.find(a => a.page_id === $json.page_id) : null; } catch (e) {}
if (!d) d = $('Split Approved').item.json;
const base = { igImage: $json.igImage, igCaption: $json.igCaption, hasImage: $json.hasImage, page_id: $json.page_id };
let stage = 'create';
try {
  // ⏱ กันชนเวลา: ทั้ง node เป็น task เดียวของ task runner ซึ่งตัดที่ 300 วิ
  // 20 ก.ย. 69 เกิดจริง: 6 ดีล → timeout กลางคัน → ดีลที่ลง Reels ไปแล้ว 3 ตัวถูกส่งไปโพสต์ภาพซ้ำอีกรอบ
  // ดังนั้นถ้าเวลาจะไม่พอสำหรับดีลถัดไป ให้ยอมถอยไปโพสต์ภาพตั้งแต่ต้น ดีกว่าโดนตัดกลางทาง
  const g = globalThis.__reel || (globalThis.__reel = {});
  if (g.exec !== $execution.id) { g.exec = $execution.id; g.t0 = Date.now(); }
  // 29 ก.ย. 69: globalThis ไม่คงค่าข้าม task (แต่ละ run ใน Loop Reels เป็น task ใหม่) → รอบ 00:00 ทุกดีลถูกนับเป็น 'ดีลแรก' ลง TikTok 6/6 → ใช้ $runIndex (0,1,2,… ต่อ execution) นับลำดับดีลแทน
  g.n = $runIndex + 1;
  if (g.n > 1) await sleep(3000);   // ช่องว่างระหว่างดีล 3 วิ (กัน rate ของ Meta)
  const spent = Date.now() - g.t0;
  // #19: แต่ละดีลเป็น task แยก (เพดาน 300 วิ/ดีล) งบนี้จึงเป็นงบรวมทั้งรอบ กันรอบยืดผิดปกติ (6 ดีล × ~65 วิ ≈ 390)
  if (spent > 480000) return { json: { ...base, reelOk: false, reelError: 'budget: ใช้ไป ' + Math.round(spent / 1000) + ' วิ ไม่พอทำคลิปอีกตัว → โพสต์ภาพแทน' } };

  // 28 ก.ย. 69: IG ถูกจำกัด 30 วัน → IG_PAUSED · TIKTOK_CLIPS: เรนเดอร์คลิป (พากย์/เพลงตามพาริตี้รอบ) แล้วส่งเข้า Telegram พร้อมแคปชัน ให้ user อัปโหลด TikTok เอง
  const IG_PAUSED = true;
  const TIKTOK_CLIPS = true;
  // 28 ก.ย. 69 ค่ำ: โพสต์เข้า TikTok ตรง (Content Posting API ใน deal-video) เฉพาะดีลแรกของรอบ (g.n ≤ perRound) — ≤7/วัน
  // ยังไม่ผ่าน audit → mode 'sandbox' + privacy 'SELF_ONLY' (บัญชีต้อง private) · ผ่านแล้วเปลี่ยนเป็น mode 'prod' + 'PUBLIC_TO_EVERYONE' · ทุกดีลยังส่งคลิปเข้า Telegram เหมือนเดิม
  const TIKTOK_DIRECT = { enabled: true, mode: 'sandbox', privacy: 'SELF_ONLY', perRound: 1 };
  // 3 ต.ค. 69 user: "คลิปเคลื่อนไหวลงที่อื่นด้วยมั้ย" → "เริ่มเลย" → Facebook Reels ของเพจ ป้ายยาดีลเด็ด เฉพาะดีลแรกของรอบ (page token = TOKEN ตัวเดียวกับ IG) · service ทำ start→upload→finish · ดู runData: fbReel
  const FB_REELS = { enabled: true, perRound: 1, page_id: '1330886503433772' };
  // 2 ต.ค. 69 user: "ส่งให้ดูก่อนโพสต์ แล้วค่อยเปิดอัตโนมัติ" → ดีลแรกของรอบ (g.n ≤ VEO.perRound) เรนเดอร์ฉาก Veo (image-to-video) แล้ว review:
  // service เก็บคลิปไว้ /tiktok/pending + ส่ง Telegram พร้อม '#veo <page_id>' ไม่โพสต์ TikTok · user ตอบกลับ "โพสต์" → Intake TG เรียก /publish · "ไม่" → /discard
  // Veo ล้ม/ข้าม (รูปแบนเนอร์ Lazada, เกินโควตาวัน, 402) → service ทำแบบเดิม (TG + TikTok ตรง) อัตโนมัติ · ดู runData: veoReview/veoPending/veo
  const VEO = { enabled: true, perRound: 1 };
  const useVeo = VEO.enabled && g.n <= VEO.perRound;
  if (IG_PAUSED) {
    if (!TIKTOK_CLIPS) return { json: { ...base, reelOk: false, reelError: 'ig paused' } };
    stage = 'tiktok-clip';
    let capT = String($json.igCaption || '');
    const cutT = capT.lastIndexOf('\n\n');
    capT = cutT > 0 ? capT.slice(0, cutT) + '\n\n' + CREDIT + capT.slice(cutT) : capT + '\n\n' + CREDIT;
    const rt = await this.helpers.httpRequest({
      method: 'POST', url: 'http://deal-video:8080/render',
      body: { name: d.name, sale: d.sale, full: d.full, desc: d.desc, cat: d.cat, img: $json.igImage, page_id: d.page_id,
              veo: useVeo || undefined,
              review: useVeo ? { url: 'https://api.telegram.org/bot' + TG_BOT + '/sendVideo', chat_id: '8336016992', caption: '🎬 Veo ดีลเด่นรอบนี้ — ' + (d.name || '') + '\n\n' + capT } : undefined,
              telegram: { url: 'https://api.telegram.org/bot' + TG_BOT + '/sendVideo', chat_id: '8336016992', caption: '🎬 คลิปสำหรับ TikTok — ' + (d.name || '') + '\n\n' + capT },
              tiktok: (TIKTOK_DIRECT.enabled && g.n <= TIKTOK_DIRECT.perRound) ? { mode: TIKTOK_DIRECT.mode, privacy: TIKTOK_DIRECT.privacy, title: capT } : undefined,
              // 3 ต.ค. 69: ส่ง fb_reel ทุกดีลให้ service เก็บ page_id/token ไว้ในไฟล์ดีล (คลิปที่ user ส่งเองจะได้ลง FB Reels ด้วย) · post:true เฉพาะดีลแรกของรอบ
              fb_reel: FB_REELS.enabled ? { page_id: FB_REELS.page_id, token: TOKEN, description: capT + '\n\n🔗 รวมดีลทั้งหมดที่ paiyaadeals.com', post: g.n <= FB_REELS.perRound } : undefined },
      json: true, timeout: 300000, ignoreHttpStatusErrors: true,   // 502 = telegram หรือ tiktok ล้มบางส่วน → อ่าน body แทน throw
    });
    const fb = rt && rt.fb_reel ? { ok: !!rt.fb_reel.ok, status: rt.fb_reel.status, phase: rt.fb_reel.phase, video_id: rt.fb_reel.video_id, error: rt.fb_reel.error } : undefined;
    const tp = rt && rt.tiktok ? { ok: !!rt.tiktok.ok, status: rt.tiktok.status, error: rt.tiktok.error, publish_id: rt.tiktok.publish_id, mode: rt.tiktok.mode, privacy: rt.tiktok.privacy } : undefined;
    return { json: { ...base, reelOk: false, tiktokClip: !!(rt && rt.sent), tiktokPost: tp, fbReel: fb, veoReview: !!(rt && rt.review), veoPending: rt && rt.pending_id, veo: (rt && rt.veo) ? { ok: !!rt.veo.ok, error: rt.veo.error, gen_s: rt.veo.gen_s } : undefined, voice: rt && rt.voice, duration: rt && rt.duration, reelError: (rt && rt.sent) ? undefined : ('tiktok-clip: ' + JSON.stringify(rt).slice(0, 200)) } };
  }

  // เครดิตเพลง CC BY ต้องมีทุกโพสต์ — แทรกก่อนบรรทัดแฮชแท็ก
  let cap = String($json.igCaption || '');
  const cut = cap.lastIndexOf('\n\n');
  cap = cut > 0 ? cap.slice(0, cut) + '\n\n' + CREDIT + cap.slice(cut) : cap + '\n\n' + CREDIT;
  if (cap.length > 2200) cap = cap.slice(0, 2200);

  const c = await this.helpers.httpRequest({
    method: 'POST', url: `https://graph.facebook.com/${V}/${IG}/media`,
    qs: { media_type: 'REELS', upload_type: 'resumable', share_to_feed: 'true', caption: cap, access_token: TOKEN },
    json: true, timeout: 30000,
  });
  if (!c || !c.id) throw new Error('no container id');

  stage = 'render+upload';
  const r = await this.helpers.httpRequest({
    method: 'POST', url: 'http://deal-video:8080/render',
    body: { name: d.name, sale: d.sale, full: d.full, desc: d.desc, cat: d.cat, img: $json.igImage,
            upload: { url: c.uri || `https://rupload.facebook.com/ig-api-upload/${V}/${c.id}`, token: TOKEN } },
    json: true, timeout: 300000,
  });
  if (!r || !r.uploaded) throw new Error('upload: ' + JSON.stringify(r));

  stage = 'processing';
  let st = {};
  for (let i = 0; i < 30; i++) {
    await sleep(3000);
    st = await this.helpers.httpRequest({
      method: 'GET', url: `https://graph.facebook.com/${V}/${c.id}`,
      qs: { fields: 'status_code,status', access_token: TOKEN }, json: true, timeout: 20000,
    });
    if (st.status_code === 'FINISHED' || st.status_code === 'ERROR' || st.status_code === 'EXPIRED') break;
  }
  if (st.status_code !== 'FINISHED') throw new Error('status ' + st.status_code + ' ' + (st.status || ''));
  if (DRY_RUN) return { json: { ...base, reelOk: false, dryRun: true, container: c.id, bytes: r.bytes, voice: r.voice, duration: r.duration } };

  stage = 'publish';
  const pub = await this.helpers.httpRequest({
    method: 'POST', url: `https://graph.facebook.com/${V}/${IG}/media_publish`,
    qs: { creation_id: c.id, access_token: TOKEN }, json: true, timeout: 60000,
  });
  if (!pub || !pub.id) throw new Error('no media id');
  return { json: { ...base, reelOk: true, reelId: pub.id, voice: r.voice, duration: r.duration } };
} catch (e) {
  let msg = e && e.message ? e.message : String(e);
  try { if (e.response && e.response.body) msg += ' | ' + JSON.stringify(e.response.body); } catch (x) {}
  return { json: { ...base, reelOk: false, reelError: stage + ': ' + mask(msg) } };
}

// รวม alert ของทุกดีลในรอบเป็น 1 ข้อความ LINE (โควตา LINE OA ฟรี 300 ข้อความ/เดือน — ส่งรายดีลหมดใน ~1 สัปดาห์
// 24 ก.ย. 69 ชน 429 แล้วทำสาย IG ไม่รัน) · นับเป็น 1 ข้อความต่อ push ไม่ว่าจะยาวแค่ไหน · 7 รอบ/วัน ≈ 217/เดือน
// เช็คโควตาก่อนทุกครั้ง: ถ้าใช้ครบแล้ว send=false → node ถัดไปไม่ยิง (TG ยังได้ครบทุกดีลเหมือนเดิม)
const alerts = $('Build Posted Alert').all().map(i => i.json.alert).filter(Boolean);
if (!alerts.length) return [];
const now = new Date(Date.now() + 7 * 3600 * 1000);
const hh = String(now.getUTCHours()).padStart(2, '0'), mm = String(now.getUTCMinutes()).padStart(2, '0');
let text = '📣 โพสต์รอบ ' + hh + ':' + mm + ' น. — ' + alerts.length + ' ดีล\n\n' + alerts.join('\n\n');
if (text.length > 4900) text = text.slice(0, 4890) + '\n…';
const headers = { Authorization: 'Bearer REPLACE_LINE_CHANNEL_TOKEN' };
let quota = null, used = null, err = '';
try {
  const q = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.line.me/v2/bot/message/quota', headers, json: true });
  const c = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.line.me/v2/bot/message/quota/consumption', headers, json: true });
  quota = (q && q.type === 'none') ? 999999 : Number(q && q.value);
  used = Number(c && c.totalUsage);
} catch (e) { err = String((e && e.message) || e).slice(0, 120); }
const send = Number.isFinite(quota) && Number.isFinite(used) && used < quota;
return [{ json: { text, quota, used, send, err, deals: alerts.length } }];

